import { z } from "zod";

const E164_PHONE_REGEX = /^\+[1-9]\d{6,14}$/;
const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
export const MAX_MESSAGING_MEDIA_BYTES = 104_857_600; // 100 MB

export const phoneHandleSchema = z.string().regex(E164_PHONE_REGEX, {
  message: "Phone number must be formatted as E.164, for example +15551234567",
});

export const emailHandleSchema = z
  .string()
  .trim()
  .toLowerCase()
  .regex(EMAIL_REGEX, { message: "Email must be a valid address" });

export const handleSchema = z.union([phoneHandleSchema, emailHandleSchema]);

const metadataSchema = z
  .record(z.string(), z.string())
  .optional()
  .refine(
    (value) => !value || Object.keys(value).length <= 20,
    "Metadata cannot contain more than 20 keys",
  );

export const mediaAttachmentSchema = z
  .object({
    url: z.string().url(),
    contentType: z.string().min(1),
    sizeBytes: z.number().int().nonnegative().max(MAX_MESSAGING_MEDIA_BYTES),
    fileName: z.string().min(1).max(240).optional(),
    width: z.number().int().positive().optional(),
    height: z.number().int().positive().optional(),
    expiresAt: z.string().datetime().optional(),
  })
  .strict();

const CHANNEL_STATUS_VALUES = ["ACTIVE", "DISABLED"] as const;
export const channelStatusSchema = z.enum(CHANNEL_STATUS_VALUES);
export type ChannelStatus = (typeof CHANNEL_STATUS_VALUES)[number];

const CHANNEL_CAPABILITY_VALUES = ["TEXT", "MEDIA"] as const;
export const channelCapabilitySchema = z.enum(CHANNEL_CAPABILITY_VALUES);
export type ChannelCapability = (typeof CHANNEL_CAPABILITY_VALUES)[number];

export const channelConfigSchema = z
  .object({
    id: z.string().min(1),
    label: z.string().min(1).max(120).optional(),
    phone: phoneHandleSchema,
    status: channelStatusSchema.default("ACTIVE"),
    capabilities: z
      .array(channelCapabilitySchema)
      .nonempty()
      .default(["TEXT", "MEDIA"]),
  })
  .strict();

export const inboundMessageSchema = z
  .object({
    id: z.string().min(1),
    channelId: z.string().min(1),
    handle: handleSchema,
    body: z.string().trim().min(1).max(4_000).optional(),
    media: z.array(mediaAttachmentSchema).max(10).default([]),
    timestamp: z.string().datetime(),
    inReplyTo: z.string().min(1).optional(),
    threadId: z.string().min(1).optional(),
    metadata: metadataSchema,
  })
  .strict()
  .superRefine((value, ctx) => {
    if (!value.body && value.media.length === 0) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: "Message must include either body text or media",
        path: ["body"],
      });
    }
  });

export const sendCommandSchema = z
  .object({
    id: z.string().min(1),
    channelId: z.string().min(1),
    handle: handleSchema,
    body: z.string().trim().min(1).max(4_000).optional(),
    mediaRefs: z.array(mediaAttachmentSchema).max(10).default([]),
    correlationId: z.string().min(1).max(128).optional(),
    retryCount: z.number().int().nonnegative().optional(),
    metadata: metadataSchema,
  })
  .strict()
  .superRefine((value, ctx) => {
    if (!value.body && value.mediaRefs.length === 0) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: "Send commands must include either body text or media",
        path: ["body"],
      });
    }
  });

// TODO(P2): Consider aligning with handler's SAFE_REACTIONS (love, like, laugh, emphasize)
// or making the filter configurable. Currently schema allows 12 types but handler blocks 8.
const REACTION_TYPE_VALUES = [
  "love",
  "like",
  "dislike",
  "laugh",
  "emphasize",
  "question",
  "-love",
  "-like",
  "-dislike",
  "-laugh",
  "-emphasize",
  "-question",
] as const;

export const reactionTypeSchema = z.enum(REACTION_TYPE_VALUES);
export type ReactionType = (typeof REACTION_TYPE_VALUES)[number];

export const sendReactionCommandSchema = z
  .object({
    type: z.literal("send_reaction"),
    id: z.string().min(1),
    channelId: z.string().min(1),
    handle: handleSchema,
    targetMessageGuid: z.string().min(1),
    chatGuid: z.string().min(1).optional(),
    reactionType: reactionTypeSchema,
    correlationId: z.string().min(1).max(128).optional(),
    metadata: metadataSchema,
  })
  .strict();

const DELIVERY_STATUS_VALUES = ["sent", "delivered", "failed"] as const;
export const deliveryStatusSchema = z.enum(DELIVERY_STATUS_VALUES);
export type DeliveryStatus = (typeof DELIVERY_STATUS_VALUES)[number];

export const deliveryReceiptSchema = z
  .object({
    id: z.string().min(1),
    commandId: z.string().min(1),
    status: deliveryStatusSchema,
    error: z.string().min(1).optional(),
    timestamp: z.string().datetime().optional(),
    channelId: z.string().min(1).optional(),
    handle: handleSchema.optional(),
    metadata: metadataSchema,
  })
  .strict();

export type InboundMessage = z.infer<typeof inboundMessageSchema>;
export type SendCommand = z.infer<typeof sendCommandSchema>;
export type SendReactionCommand = z.infer<typeof sendReactionCommandSchema>;
export type DeliveryReceipt = z.infer<typeof deliveryReceiptSchema>;
export type ChannelConfig = z.infer<typeof channelConfigSchema>;
